<script setup lang="ts">
import DaysItem from '@/pages/home/components/doashuri/daysItem/index.vue'
import Qiandao from  "@/pages/home/components/doashuri/qiandao.vue"
import {getDaysMatter,postDaysMatterAdd,postDaysMatterxiugai} from "@/api/home"

// import { DaysMatterData } from '@/api/home/type';
import { ref, onMounted  } from 'vue';
import { reactive } from 'vue'
import type { FormInstance, FormRules } from 'element-plus'
const xiugaiisVisible = ref(false);
//修改倒数日
const currentDaysMatterId = ref('');
const handleItemClick = (daysMatterId) => {
  xiugaiisVisible.value = true;
  currentDaysMatterId.value = daysMatterId;
  console.log(daysMatterId)
};
const xiugaionSubmit= async ()=>{
  const isValid = await ruleFormRef.value.validate();
  if (isValid) {
    // 转换 targetDay 的格式
    const date = new Date(form.targetDay);
    const year = date.getFullYear();
    const month = (date.getMonth() + 1).toString().padStart(2, '0'); // 月份是从0开始的，所以加1
    const day = date.getDate().toString().padStart(2, '0');
    const formattedTargetDay = `${year}-${month}-${day}`;

    // 在提交之前，将 repeatType 转换为数字
    const dataToSubmit = {
      ...form,
      targetDay: formattedTargetDay, // 使用转换后的日期格式
      repeatType: Number(form.repeatType),
      daysMatterId: currentDaysMatterId.value
    };

    console.log('修改接口准备提交的数据:', JSON.stringify(dataToSubmit, null, 2));

    try {
      const response = await postDaysMatterxiugai(dataToSubmit);
      console.log('后端响应:', response);
      xiugaiisVisible.value = false;
      getDaysMatterdata();
    } catch (error) {
      console.error('提交数据失败:', error.response ? error.response.data : error.message);
      // 这里可以给用户显示错误信息
    }
  } else {
    console.log('验证失败，不提交数据');
  }
};
const ruleFormRef = ref<FormInstance>()
  const rules: FormRules = {
  daysMatterTitle: [
    { required: true, message: '事件名称不能为空', trigger: 'blur' }
  ],
  targetDay: [
    { required: true, message: '截止日期不能为空', trigger: 'change' }
  ]
}
const form = reactive({
  
  daysMatterTitle: '',
  targetDay: '',
  repeatType:'1',
  repeatNum:1,
  backdropUrl: "背景图片", 
  status: 1 // 假设状态默认为1
  
})
const repeatType = ref('')
const num = ref(1)
const options = [
  {
    value: '1',
    label: '不重复',
  },
  {
    value: '2',
    label: '按年',
  },
  {
    value: '3',
    label: '按月',
  },
  {
    value: '4',
    label: '按周',
  },
]
const onSubmit = async () => {
  const isValid = await ruleFormRef.value.validate();
  if (isValid) {
    // 转换 targetDay 的格式
    const date = new Date(form.targetDay);
    const year = date.getFullYear();
    const month = (date.getMonth() + 1).toString().padStart(2, '0'); // 月份是从0开始的，所以加1
    const day = date.getDate().toString().padStart(2, '0');
    const formattedTargetDay = `${year}-${month}-${day}`;

    // 在提交之前，将 repeatType 转换为数字
    const dataToSubmit = {
      ...form,
      targetDay: formattedTargetDay, // 使用转换后的日期格式
      repeatType: Number(form.repeatType),
      
    };

    console.log('准备提交的数据:', JSON.stringify(dataToSubmit, null, 2));

    try {
      const response = await postDaysMatterAdd(dataToSubmit);
      console.log('后端响应:', response);
      centerDialogVisible.value=false;
      getDaysMatterdata();
    } catch (error) {
      console.error('提交数据失败:', error.response ? error.response.data : error.message);
      // 这里可以给用户显示错误信息
    }
  } else {
    console.log('验证失败，不提交数据');
  }
};


let DaysMatterdata =([]);
const centerDialogVisible = ref(false)
const currentTime = ref(new Date());
const formattedTime = ref({
  pm: 'AM',
  time: ''
});

const formatTime = (date: any) => {
  let hours = date.getHours();
  let minutes = date.getMinutes();
  let ampm = hours >= 12 ? 'PM' : 'AM';

  hours = hours % 12;
  hours = hours ? hours : 12; 
  hours = hours < 10 ? '0' + hours : hours; 
  minutes = minutes < 10 ? '0' + minutes : minutes; 

  return {
    pm: ampm,
    time: `${hours}:${minutes}`
  };
};
formattedTime.value = formatTime(currentTime.value);

const updateTime = () => {
  currentTime.value = new Date();
  formattedTime.value = formatTime(currentTime.value);
};

onMounted(() => {
  setInterval(updateTime, 1000);

});
//获取倒数日数据展示
onMounted(async () => {
  await getDaysMatterdata();
 
});


// 获取倒数日数据并处理
const getDaysMatterdata = async () => {
  const result = await getDaysMatter();

   DaysMatterdata = result.data
    console.log(DaysMatterdata)
};
</script>
